 const r=setup({platform:'MP-WEIXIN',sdk:()=>{}}),m=mount(r);try{await tick();fire(css(m.tree,'combination-card')[0]);fire(css(m.tree,'combination-card')[0]);assert.equal(r.subscriptions.length,1);assert.deepEqual(r.navigations,[]);fire(css(m.tree,'combination-more')[0]);assert.deepEqual(r.navigations,['/pages/activity/index?type=combination']);assert.equal(r.subscriptions.length,1);r.subscriptions[0].fail({});await tick();assert.deepEqual(r.navigations,['/pages/activity/index?type=combination','/pages/activity/detail?id=901']);noWrites(r);}finally{finish(r,m);}
