 const wait=deferred(),r=setup({platform:'MP-WEIXIN',templateSend:()=>wait.promise,sdk:()=>{}}),m=mount(r);try{await tick();assert.equal(r.c.loaded.value,true);assert.equal(r.controller.templateIds.value,null);fire(css(m.tree,'combination-card')[0]);assert.deepEqual(r.navigations,['/pages/activity/detail?id=901']);assert.equal(r.subscriptions.length,0);wait.resolve({data:templateValue});await tick();assert.deepEqual(r.navigations,['/pages/activity/detail?id=901']);assert.equal(r.subscriptions.length,0);fire(css(m.tree,'combination-card')[0]);assert.equal(r.subscriptions.length,1);r.subscriptions[0].success({});await tick();assert.equal(r.navigations.length,2);noWrites(r);}finally{wait.resolve({data:null});finish(r,m);}
