for(const boundary of['account','accountABA','session','count','raw','rawABA','activeABA','disabled','legacyDisabled','hidden','reloadSameID','dispose','unmount'])test(`pending native subscription cannot navigate or release current state across${boundary}`,()=>clocked(async()=>{
 const r=setup({platform:'MP-WEIXIN',sdk:()=>{}}),m=mount(r);try{await tick();fire(css(m.tree,'combination-card')[0]);const old=r.subscriptions[0];assert.ok(old);await crossBoundary(boundary,r,m);const reads=r.calls.length,failures=copy(r.checkout.imageFailures.value);old.success({'provider-pink-true':'accept'});old.fail({});await tick();assert.deepEqual(r.navigations,[]);assert.equal(r.calls.length,reads);assert.deepEqual(r.checkout.imageFailures.value,failures);if(!['disabled','legacyDisabled','hidden','dispose','unmount'].includes(boundary)){fire(css(m.tree,'combination-card')[0]);assert.equal(r.subscriptions.length,2);old.success({});assert.equal(r.controller.subscriptionPending.value,true,'Old completion must not release a newer pending SDK');r.subscriptions[1].fail({});await tick();assert.deepEqual(r.navigations,['/pages/activity/detail?id=901']);}noWrites(r);}finally{finish(r,m);}
}));
